select
students.*
from students students

    and students.id = #{id}
    and students.username = #{username}
    and students.password = #{password}
    and students.header_img = #{headerImg}
    and students.name like concat('%',#{name},'%')
    and students.tel = #{tel}
    and students.localtion = #{localtion}
    and students.info = #{info}
    and students.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from students students

    and students.id = #{id}
    and students.username = #{username}
